#include <iostream>

class Box {
private:
    double width;
    double height;

public:
    Box(double w, double h) : width(w), height(h) {}

    // Cach 1: Khai bao friend trong lop, dinh nghia ben ngoai
    friend void printDimensions(const Box& b);

    // Cach 2: Dinh nghia friend truc tiep ben trong lop
    friend double computeArea(const Box& b) {
        // Khong co con tro 'this'; truy cap truc tiep b.width, b.height
        return b.width * b.height;
    }
};

// Dinh nghia ngoai cua Cach 1 (khong dung tu khoa friend, khong dung Box::)
void printDimensions(const Box& b) {
    std::cout << "Dimensions: " << b.width << " x " << b.height << "\n";
}

int main() {
    Box box(3.5, 4.0);
    printDimensions(box);
    std::cout << "Area: " << computeArea(box) << "\n";
    return 0;
}

#include <iostream>

// Forward declaration can thiet cho ham ban da lop
class Vector2D;

class Point2D {
private:
    double x;
    double y;
public:
    Point2D(double px, double py) : x(px), y(py) {}

    // Khai bao ham ban cua lop Point2D
    friend Point2D translate(const Point2D& p, const Vector2D& v);
    friend void printPoint(const Point2D& p);
};

class Vector2D {
private:
    double dx;
    double dy;
public:
    Vector2D(double vx, double vy) : dx(vx), dy(vy) {}

    // Khai bao cung ham do la ban cua lop Vector2D
    friend Point2D translate(const Point2D& p, const Vector2D& v);
};

// Dinh nghia ham ban cua ca hai lop: truy cap p.x, p.y va v.dx, v.dy
Point2D translate(const Point2D& p, const Vector2D& v) {
    return Point2D(p.x + v.dx, p.y + v.dy);
}

void printPoint(const Point2D& p) {
    std::cout << "Point(" << p.x << ", " << p.y << ")\n";
}

int main() {
    Point2D p(1.5, 2.5);
    Vector2D v(3.0, 4.0);
    Point2D pResult = translate(p, v);
    printPoint(pResult);
    return 0;
}
